refentry.refsect1:
&reftitle.description;
boolodbc_next_result Odbc\Resultstatement
Verifica se sono disponibili altri set di risultati e consente di accedere al set di risultati successivo tramite odbc_fetch_array, odbc_fetch_row, odbc_result, ecc.

  &reftitle.examples;



    odbc_next_result


<?php
$r_Connection = odbc_connect($dsn, $username, $password);

$s_SQL = <<<END_SQL
SELECT 'A'
SELECT 'B'
SELECT 'C'
END_SQL;

$r_Results = odbc_exec($r_Connection, $s_SQL);

$a_Row1 = odbc_fetch_array($r_Results);
$a_Row2 = odbc_fetch_array($r_Results);
echo "Contenuto del primo set di risultati ";
var_dump($a_Row1, $a_Row2);

echo "Recupero del secondo set di risultati ";
var_dump(odbc_next_result($r_Results));

$a_Row1 = odbc_fetch_array($r_Results);
$a_Row2 = odbc_fetch_array($r_Results);
echo "Contenuto del secondo set di risultati ";
var_dump($a_Row1, $a_Row2);

echo "Recupero del terzo set di risultati ";
var_dump(odbc_next_result($r_Results));

$a_Row1 = odbc_fetch_array($r_Results);
$a_Row2 = odbc_fetch_array($r_Results);
echo "Contenuto del terzo set di risultati ";
var_dump($a_Row1, $a_Row2);

echo "Tentativo di recuperare un quarto set di risultati ";
var_dump(odbc_next_result($r_Results));
?>


    &example.outputs;


Contenuto del primo set di risultati array(1) {
  ["A"]=>
  string(1) "A"
}
bool(false)
Recupero del secondo set di risultati bool(true)
Contenuto del secondo set di risultati array(1) {
  ["B"]=>
  string(1) "B"
}
bool(false)
Recupero del terzo set di risultati bool(true)
Contenuto del terzo set di risultati array(1) {
  ["C"]=>
  string(1) "C"
}
bool(false)
Tentativo di recuperare un quarto set di risultati bool(false)
